changeSet.sql:
UPDATE registration.financial_periods
SET status = CASE status WHEN 'ACCOUNTED' THEN 'CLOSED' ELSE 'OPEN' END;
ALTER TABLE registration.financial_periods
    ADD CONSTRAINT ck_financial_periods_on_status CHECK (status IN ('OPEN', 'CLOSED'));

rollback.sql:
ALTER TABLE registration.financial_periods
    DROP CONSTRAINT ck_financial_periods_on_status;
UPDATE registration.financial_periods
SET status = CASE status WHEN 'CLOSED' THEN 'ACCOUNTED' ELSE 'ACTIVE' END;
